/** One row of `workspaces.list`; the contract lives in `src/rpc.ts`. */
interface WorkspaceListRow {
  store: string
  root: string | null
  points: number | null
  complete: boolean | null
  profile: string | null
  updatedAt: string | null
  source: "registry" | "collection"
}

/** Points and completion state of one own collection; null when unreadable. */
async function readOwnCollectionInfo(client: Qdrant, store: string): Promise<OwnStoreInfo | null> {
  try {
    return await getOwnStoreInfo(client, store)
  } catch {
    // Raced with a deletion, or the collection vanished mid-listing.
    return null
  }
}

function settingsView(settings: IndexingSettings, homeDir?: string): Record<string, unknown> {
  const custom = settings.customProfiles?.[settings.provider]?.[settings.modelId]
  return {
    vectorStore: settings.vectorStore,
    qdrantUrl: settings.qdrantUrl,
    qdrantApiKey: maskSecret(settings.qdrantApiKey) ?? "",
    lancedbDirectory: settings.lancedbDirectory,
    provider: settings.provider,
    model: settings.modelId,
    dimension: settings.dimension,
    queryPrefix: custom?.queryPrefix ?? settings.queryPrefix ?? "",
    maxInputTokens: custom?.maxInputTokens ?? getModelMaxInputTokens(settings.provider, settings.modelId),
    modelScoreThreshold: custom?.scoreThreshold ?? null,
    importFromKilo: settings.importFromKilo,
    searchKilo: settings.searchKilo !== false,
    autoRefresh: settings.autoRefresh,
    enabled: settings.enabled,
    codegraph: settings.codegraph !== false,
    searchMaxResults: settings.searchMaxResults,
    searchMinScore: settings.searchMinScore ?? null,
    embeddingBatchSize: settings.embeddingBatchSize,
    fileExtensions: settings.fileExtensions,
    kiloVectorStore: settings.kiloVectorStore,
    // Which providers actually have a credential, as a list rather than one
    // boolean per provider. The booleans only ever covered Mistral and OpenAI,
    // so a settings page with a Gemini key configured reported "none
    // configured" - and every provider added afterwards would have needed
    // another field threaded through the RPC, the schema and the page.
    configuredProviders: configuredProviders(settings.credentials),
    settingsFile: settingsFilePath(homeDir),
    warnings: settings.warnings,
  }
}

/**
 * Providers with a usable credential.
 *
 * A base URL counts for the two providers that authenticate with one, since a
 * configured Ollama or OpenAI-compatible server needs no key.
 */
function configuredProviders(credentials: ProviderCredentials): string[] {
  const configured: string[] = []
  if (credentials.mistralApiKey) configured.push("mistral")
  if (credentials.openAiApiKey) configured.push("openai")
  if (credentials.geminiApiKey) configured.push("gemini")
  if (credentials.voyageApiKey) configured.push("voyage")
  if (credentials.openRouterApiKey) configured.push("openrouter")
  if (credentials.ollamaBaseUrl) configured.push("ollama")
  if (credentials.openAiCompatibleBaseUrl) configured.push("openai-compatible")
  return configured
}

/**
 * The profile the settings describe.
 *
 * Only the identity of the model is needed to compare against a Kilo index;
 * the dimension is part of the comparison, so it has to come from somewhere.
 * `settings.dimension` is 0 for a model the catalog does not know, and a
 * comparison against a zero dimension would report every source as
 * incompatible, which is as wrong as reporting every one as compatible.
 */
function profileFor(settings: IndexingSettings): EmbeddingProfile | undefined {
  const dimension = settings.dimension || modelDimensionFor(settings, settings.provider, settings.modelId) || 0
  if (!dimension) return undefined
  return { provider: settings.provider, modelId: settings.modelId, dimension }
}

/**
 * The models this provider offers, and which of them can import from Kilo.
 *
 * The catalog was only ever used to look up a dimension, so it was invisible:
 * a model id had to be known in advance to be used. Which entries Kilo also
 * knows is the one thing that decides whether an import will be accepted, so
 * it is stated rather than left to be discovered by a refused build.
 */
function describeAvailableModels(settings: IndexingSettings): string[] {
  const custom = settings.customProfiles?.[settings.provider] ?? {}
  const models = [...new Set([...listModelIds(settings.provider), ...Object.keys(custom)])]
  const note = isLiveTested(settings.provider)
    ? []
    : [
        `- **Note:** the ${settings.provider} adapter has not been exercised against the real API; it is built from the provider's documentation. See "How far each provider has actually been tested" in the README.`,
      ]
  if (models.length === 0) {
    return [...note, `- **Models:** this provider has no catalog; set \`model\` to whatever your endpoint serves`]
  }
  const render = (modelId: string) => {
    const dimension = custom[modelId]?.dimension ?? getModelDimension(settings.provider, modelId)
    const own = custom[modelId] !== undefined && getModelProfile(settings.provider, modelId) === undefined
    const importer = own ? " — custom model" : isKiloMirrored(settings.provider, modelId) === false ? " — not importable from Kilo" : ""
    return `\`${modelId}\`${dimension ? ` (${dimension}d)` : ""}${importer}`
  }
  return [...note, `- **Models for ${settings.provider}:** ${models.map(render).join(" · ")}`]
}

function summarizeReport(report: {
  durationMs: number
  chunksUpserted: number
  batches: number
  imported?: { source: string; kind: string; chunks: number }
  importedSources?: Array<{ source: string; kind: string; chunks: number; role?: string }>
  errors: string[]
  warnings: string[]
}): string {
  const parts = [`Finished in ${(report.durationMs / 1000).toFixed(1)}s`]
  // `importedSources` is additive; a single source keeps the older wording so
  // existing callers read exactly what they used to.
  const sources: Array<{ source: string; kind: string; chunks: number; role?: string }> =
    report.importedSources ?? (report.imported ? [report.imported] : [])
  if (sources.length === 1) {
    const entry = sources[0]!
    const role = entry.role ? `${entry.role} ` : ""
    parts.push(`imported ${entry.chunks} chunks from ${role}${entry.kind} ${entry.source} (no embedding calls)`)
  } else if (sources.length > 1) {
    const total = sources.reduce((sum, entry) => sum + entry.chunks, 0)
    const detail = sources
      .map((entry) => `${entry.role ? `${entry.role} ` : ""}${entry.kind} ${entry.source} (${entry.chunks} chunks)`)
      .join(" · ")
    parts.push(`imported ${total} chunks from ${sources.length} Kilo sources: ${detail} (no embedding calls)`)
  }
  parts.push(`${report.chunksUpserted} chunks in ${report.batches} batch(es)`)
  if (report.errors.length > 0) parts.push(`errors: ${report.errors.slice(0, 3).join("; ")}`)
  if (report.warnings.length > 0) parts.push(`warnings: ${report.warnings.slice(0, 3).join("; ")}`)
  return parts.join(" · ")
}

/**
 * Drop the metadata caches and the auto-refresh throttle after a write.
 *
 * Both are keyed by workspace and cheap to rebuild; letting them sit out their
 * TTL would keep reporting the pre-write collection, points or profile, and
 * would skip the freshness check a just-written workspace needs.
 */
function invalidateCaches(root?: string): void {
  invalidateSearchCaches(root)
  invalidateAutoRefresh(root)
}

